<body>
  <div class="sheet">

    <div class="title-row">
      Tax Invoice
      <span class="tag">(Buyer's Copy — Reconstructed)</span>
    </div>

    <!-- Seller + Invoice meta -->
    <div class="top-grid">
      <div class="seller-cell">
        <div class="logo-box">${re}</div>
        <div>
          <div class="seller-name">${g(n.name)}</div>
          <div class="seller-addr">${g(n.address)||h}</div>
          <div class="seller-addr">GSTIN/UIN: ${n.gst_number?g(n.gst_number):h}</div>
          <div class="seller-addr">State Name: ${n.state?g(n.state):h}</div>
          <div class="seller-addr">E-Mail: ${n.email?g(n.email):h}</div>
        </div>
      </div>
      <table class="meta-tbl">
        <tr>
          <td class="half"><span class="k">Invoice No.</span><br/><span class="v">${m?g(m):h}</span></td>
          <td class="half"><span class="k">Dated</span><br/><span class="v">${Ft(R)}</span></td>
        </tr>
        <tr>
          <td><span class="k">Delivery Note</span><br/>${h}</td>
          <td><span class="k">Mode/Terms of Payment</span><br/>${n.payment_terms?g(n.payment_terms):h}</td>
        </tr>
        <tr>
          <td><span class="k">Reference No. &amp; Date</span><br/>${h}</td>
          <td><span class="k">Other References</span><br/>${h}</td>
        </tr>
        <tr>
          <td><span class="k">Buyer's Order No.</span><br/>${F?g(F):h}</td>
          <td><span class="k">Dated</span><br/>${ie?Ft(ie):h}</td>
        </tr>
        <tr>
          <td><span class="k">Dispatch Doc No.</span><br/>${h}</td>
          <td><span class="k">Delivery Note Date</span><br/>${h}</td>
        </tr>
        <tr>
          <td><span class="k">Dispatched through</span><br/>${K?g(K):h}</td>
          <td><span class="k">Destination</span><br/>${X?g(X):h}</td>
        </tr>
        <tr>
          <td><span class="k">Bill of Lading/LR-RR No.</span><br/>${ee?g(ee):h}</td>
          <td><span class="k">Motor Vehicle No.</span><br/>${M?g(M):h}</td>
        </tr>
        <tr>
          <td colspan="2"><span class="k">Terms of Delivery</span><br/>${T?g(T):h}</td>
        </tr>
      </table>
    </div>

    <!-- Consignee (Ship to) -->
    <div class="party-box">
      <div class="party-lbl">Consignee (Ship to)</div>
      <div class="party-name">${g(c.client_name)}</div>
      <div class="party-addr">${c.address?g(c.address):h}</div>
      <div class="party-row"><span class="k">GSTIN/UIN</span><span>: ${c.gstin?g(c.gstin):h}</span></div>
    </div>

    <!-- Buyer (Bill to) -->
    <div class="party-box">
      <div class="party-lbl">Buyer (Bill to)</div>
      <div class="party-name">${g(c.client_name)}</div>
      <div class="party-addr">${c.address?g(c.address):h}</div>
      <div class="party-row"><span class="k">GSTIN/UIN</span><span>: ${c.gstin?g(c.gstin):h}</span></div>
    </div>

    <!-- Items -->
    <table class="items">
      <thead>
        <tr>
          <th style="width:24px">Sl<br/>No.</th>
          <th class="tl">Description of Goods</th>
          <th>HSN/SAC</th>
          <th>Quantity</th>
          <th class="tr">Rate<br/>(Incl. of Tax)</th>
          <th class="tr">Rate</th>
          <th>per</th>
          <th class="tr">Amount</th>
        </tr>
      </thead>
      <tbody>${q}</tbody>
      <tfoot>
        <tr class="items-total-row">
          <td colspan="3"></td>
          <td class="tc">${L.toLocaleString("en-IN")}</td>
          <td colspan="3"></td>
          <td class="tr">${w(C)}</td>
        </tr>
        ${ce}
        ${pe}
        <tr class="grand-row">
          <td colspan="3" class="tl">Total</td>
          <td class="tc">${L.toLocaleString("en-IN")} ${((Ne=$[0])==null?void 0:Ne.unit)||"Nos"}</td>
          <td colspan="3"></td>
          <td class="tr">₹ ${w(B)}</td>
        </tr>
      </tfoot>
    </table>

    <div class="words-row">
      <span class="eoe">E. &amp; O.E</span>
      <span class="lbl">Amount Chargeable (in words)</span>
      <span class="amt">${At(B)}</span>
    </div>

    <!-- QR (business's UPI ID from Shop Settings) + HSN summary -->
    <div class="qr-summary-grid">
      <div class="qr-cell">
        ${b?`<img src="${b}" alt="Scan to Pay" style="width:100px;height:100px"/><span class="qr-label">Scan to Pay</span><span class="qr-label">${g(U)}</span>`:'<div class="qr-box">Scan to Pay<br/>(UPI ID not set)</div>'}
      </div>
      <div style="padding:6px;border-top:none">
        <table class="hsn">
          <thead>
            <tr><th rowspan="2">HSN/SAC</th><th rowspan="2">Taxable<br/>Value</th><th colspan="2">CGST</th><th colspan="2">SGST/UTGST</th><th rowspan="2">Total<br/>Tax Amount</th></tr>
            <tr><th>Rate</th><th>Amount</th><th>Rate</th><th>Amount</th></tr>
          </thead>
          <tbody>${je}</tbody>
          <tfoot>
            <tr><td>Total</td><td class="tr">${w(C)}</td><td></td><td class="tr">${w(H)}</td><td></td><td class="tr">${w(y)}</td><td class="tr">${w(H+y)}</td></tr>
          </tfoot>
        </table>
      </div>
    </div>

    <div class="words-row">
      <span class="lbl">Tax Amount (in words)</span>
      <span class="amt">${At(H+y)}</span>
    </div>

    <!-- Bank details -->
    <div class="bank-box">
      <div class="bank-title">Company's Bank Details</div>
      <div class="bank-row"><span class="k">A/c Holder's Name</span><span>: ${n.bank_account_name?g(n.bank_account_name):h}</span></div>
      <div class="bank-row"><span class="k">Bank Name</span><span>: ${n.bank_name?g(n.bank_name):h}</span></div>
      <div class="bank-row"><span class="k">A/c No.</span><span>: ${n.bank_account_number?g(n.bank_account_number):h}</span></div>
      <div class="bank-row"><span class="k">Branch &amp; IFS Code</span><span>: ${n.bank_ifsc_code?g(n.bank_ifsc_code):h}</span></div>
    </div>

    <div class="decl-row">
      <div class="decl-col">
        <div class="h">Declaration</div>
        We declare that this invoice shows the actual price of the goods described and that all particulars are true and correct.
      </div>
      <div class="sign-col">
        <div class="sign-for">for ${g(n.name)}</div>
        <div class="sign-space"></div>
        <div class="sign-label">Authorised Signatory</div>
      </div>
    </div>

    <div class="foot-note">This is a Computer Generated Invoice</div>
  </div>

  <div class="actions">
    <button class="btn btn-secondary" onclick="window.close()">Close</button>
    <button class="btn btn-primary" onclick="window.print()">Save as PDF / Print</button>
  </div>
</body>
